'use strict';
const $=id=>document.getElementById(id), ROWS=100, COLS=26, FUNCS=['SUM','AVG','MIN','MAX','COUNT'];
const state={workbook:null,sheet:null,users:[],revision:0,revisions:[],sel:{r1:1,c1:1,r2:1,c2:1},anchor:{r:1,c:1},undo:[],redo:[],dirty:new Set(),conflicts:new Set(),editing:false,dragging:false,formulaPick:false,sessionId:crypto.randomUUID(),presence:[],saveTimer:null,saving:false,lastFind:-1};
const colors=['#e5484d','#8e4ec6','#0e9888','#f76808','#3e63dd','#d6409f','#30a46c','#ab6400'];
const clone=x=>JSON.parse(JSON.stringify(x));
function colName(c){let s='';while(c){c--;s=String.fromCharCode(65+c%26)+s;c=Math.floor(c/26)}return s}
function addr(r,c){return colName(c)+r}
function parseAddr(a){const m=/^([A-Z]{1,3})([1-9]\d*)$/.exec((a||'').toUpperCase());if(!m)return null;let c=0;for(const x of m[1])c=c*26+x.charCodeAt(0)-64;return {r:+m[2],c}}
function bounds(){const s=state.sel;return {r1:Math.min(s.r1,s.r2),r2:Math.max(s.r1,s.r2),c1:Math.min(s.c1,s.c2),c2:Math.max(s.c1,s.c2)}}
function raw(a){return state.sheet.cells[a]||''}
function put(a,v){if(v==='')delete state.sheet.cells[a];else state.sheet.cells[a]=String(v)}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

class FormulaError extends Error{}
function tokenize(s){const out=[];let i=0;while(i<s.length){if(/\s/.test(s[i])){i++;continue}const rest=s.slice(i);let m;if(m=/^\d+(?:\.\d+)?/.exec(rest)){out.push(['num',m[0]]);i+=m[0].length}else if(m=/^[A-Za-z]+[1-9]\d*/.exec(rest)){out.push(['ref',m[0].toUpperCase()]);i+=m[0].length}else if(m=/^[A-Za-z]+/.exec(rest)){out.push(['id',m[0].toUpperCase()]);i+=m[0].length}else if('+-*/(),:'.includes(s[i])){out.push([s[i],s[i]]);i++}else throw new FormulaError('#FORMULA!')}return out}
function evaluateCell(address,stack=new Set()){const value=raw(address);if(!value.startsWith('='))return value;if(stack.has(address))return '#CIRCULAR!';stack=new Set(stack);stack.add(address);try{const t=tokenize(value.slice(1));let p=0;const peek=x=>t[p]?.[0]===x, take=x=>{if(!peek(x))throw new FormulaError('#FORMULA!');return t[p++][1]};
 const number=v=>{if(typeof v==='string'&&v.startsWith('#'))throw new FormulaError(v);const n=Number(v);return Number.isFinite(n)?n:0};
 function primary(){if(peek('num'))return +take('num');if(peek('-')){take('-');return -number(primary())}if(peek('+')){take('+');return number(primary())}if(peek('(')){take('(');const v=expr();take(')');return v}if(peek('ref')){const a=take('ref');if(peek(':')){take(':');const z=take('ref');return rangeValues(a,z,stack)}return evaluateCell(a,stack)}if(peek('id')){const f=take('id');if(!FUNCS.includes(f))throw new FormulaError('#NAME?');take('(');let vals=[];if(!peek(')'))do{const v=expr();vals.push(...(Array.isArray(v)?v:[v]));if(!peek(','))break;take(',')}while(true);take(')');const nums=vals.filter(v=>v!==''&&!String(v).startsWith('#')).map(Number).filter(Number.isFinite);if(f==='SUM')return nums.reduce((a,b)=>a+b,0);if(f==='COUNT')return nums.length;if(!nums.length)return 0;if(f==='AVG')return nums.reduce((a,b)=>a+b,0)/nums.length;if(f==='MIN')return Math.min(...nums);return Math.max(...nums)}throw new FormulaError('#FORMULA!')}
 function term(){let v=primary();while(peek('*')||peek('/')){const op=take(t[p][0]),q=number(primary());v=op==='*'?number(v)*q:q===0?(()=>{throw new FormulaError('#DIV/0!')})():number(v)/q}return v}function expr(){let v=term();while(peek('+')||peek('-')){const op=take(t[p][0]),q=term();v=op==='+'?number(v)+number(q):number(v)-number(q)}return v}const result=expr();if(p!==t.length||Array.isArray(result))throw new FormulaError('#FORMULA!');return Number.isFinite(result)?String(Math.round(result*1e10)/1e10):'#FORMULA!'}catch(e){return e instanceof FormulaError?e.message:'#FORMULA!'}}
function rangeValues(a,z,stack){const x=parseAddr(a),y=parseAddr(z);if(!x||!y)throw new FormulaError('#REF!');const vals=[];for(let r=Math.min(x.r,y.r);r<=Math.max(x.r,y.r);r++)for(let c=Math.min(x.c,y.c);c<=Math.max(x.c,y.c);c++)vals.push(evaluateCell(addr(r,c),stack));return vals}

function buildGrid(){const g=$('grid');let h='<div class="corner"></div>';for(let c=1;c<=COLS;c++)h+=`<div class="col-head">${colName(c)}</div>`;for(let r=1;r<=ROWS;r++){h+=`<div class="row-head">${r}</div>`;for(let c=1;c<=COLS;c++)h+=`<div class="cell" role="gridcell" data-r="${r}" data-c="${c}" id="cell-${r}-${c}"></div>`}g.innerHTML=h}
function cellEl(r,c){return $(`cell-${r}-${c}`)}
function render(){if(!state.sheet)return;const b=bounds(), formula=state.editing&&$('editor').value.startsWith('=')?$('editor').value:'';const refs=new Set((formula.match(/[A-Z]+[1-9]\d*(?::[A-Z]+[1-9]\d*)?/gi)||[]).flatMap(x=>{const [a,z=a]=x.toUpperCase().split(':');const p=parseAddr(a),q=parseAddr(z),v=[];if(p&&q)for(let r=Math.min(p.r,q.r);r<=Math.max(p.r,q.r);r++)for(let c=Math.min(p.c,q.c);c<=Math.max(p.c,q.c);c++)v.push(addr(r,c));return v}));
 for(let r=1;r<=ROWS;r++)for(let c=1;c<=COLS;c++){const el=cellEl(r,c),a=addr(r,c),v=raw(a),shown=v.startsWith('=')?evaluateCell(a):v;el.textContent=shown;el.title=v;el.className='cell';if(r>=b.r1&&r<=b.r2&&c>=b.c1&&c<=b.c2)el.classList.add('selected');if(r===state.sel.r2&&c===state.sel.c2)el.classList.add('active');if(refs.has(a))el.classList.add('formula-ref');if(state.conflicts.has(a))el.classList.add('conflict');if(String(shown).startsWith('#'))el.classList.add('error-value')}
 renderPresence();const a=addr(state.sel.r2,state.sel.c2);$('cell-readout').textContent=a;$('name-box').value=b.r1===b.r2&&b.c1===b.c2?a:`${addr(b.r1,b.c1)}:${addr(b.r2,b.c2)}`;$('formula-bar').value=raw(a);$('revision').textContent=`Revision ${state.revision}`;updateHistoryMeta()}
function select(r,c,extend=false){r=Math.max(1,Math.min(ROWS,r));c=Math.max(1,Math.min(COLS,c));if(extend){state.sel.r2=r;state.sel.c2=c}else{state.sel={r1:r,c1:c,r2:r,c2:c};state.anchor={r,c}}render();cellEl(r,c).scrollIntoView({block:'nearest',inline:'nearest'});sendPresence()}
function selectRange(a,z=a){const p=parseAddr(a),q=parseAddr(z);if(!p||!q||p.r>ROWS||q.r>ROWS||p.c>COLS||q.c>COLS)return message('Address is outside the grid',true);state.sel={r1:p.r,c1:p.c,r2:q.r,c2:q.c};state.anchor={r:p.r,c:p.c};render();cellEl(p.r,p.c).scrollIntoView({block:'nearest',inline:'nearest'});sendPresence()}
function message(text,bad=false){$('message').textContent=text;$('message').className=bad?'failed':'';clearTimeout(message.t);message.t=setTimeout(()=>$('message').textContent='',4000)}
function setSaveState(s){const el=$('save-state');el.textContent=s[0].toUpperCase()+s.slice(1);el.className=s}
function applyChanges(changes,label,record=true){const actual=[];for(const x of changes){const old=raw(x.address),value=String(x.value??'');if(old!==value){actual.push({address:x.address,old,value});put(x.address,value);state.dirty.add(x.address)}}if(!actual.length)return;if(record){state.undo.push({label,changes:actual});state.redo=[]}setSaveState('dirty');render();scheduleSave()}
function undo(){const a=state.undo.pop();if(!a)return;for(const x of a.changes){put(x.address,x.old);state.dirty.add(x.address)}state.redo.push(a);setSaveState('dirty');render();scheduleSave()}
function redo(){const a=state.redo.pop();if(!a)return;for(const x of a.changes){put(x.address,x.value);state.dirty.add(x.address)}state.undo.push(a);setSaveState('dirty');render();scheduleSave()}
function startEdit(seed=null){const a=addr(state.sel.r2,state.sel.c2),el=cellEl(state.sel.r2,state.sel.c2),ed=$('editor'),wrap=$('grid-wrap');state.editing=true;const er=el.getBoundingClientRect(),wr=wrap.getBoundingClientRect();ed.style.cssText=`display:block;left:${er.left-wr.left+wrap.scrollLeft}px;top:${er.top-wr.top+wrap.scrollTop}px;width:${Math.max(er.width,180)}px;height:${er.height}px`;ed.value=seed===null?raw(a):seed;ed.dataset.address=a;ed.focus();ed.select();formulaAssist()}
function commitEdit(move=0){if(!state.editing)return;const ed=$('editor'),a=ed.dataset.address,v=ed.value;state.editing=false;ed.style.display='none';$('suggestions').style.display='none';applyChanges([{address:a,value:v}],`Edit ${a}`);$('grid-wrap').focus();if(move){const p=parseAddr(a);select(p.r+move,p.c)}}
function cancelEdit(){state.editing=false;$('editor').style.display='none';$('suggestions').style.display='none';render();$('grid-wrap').focus()}
function formulaAssist(){const ed=$('editor'),box=$('suggestions');if(!state.editing||!ed.value.startsWith('=')){box.style.display='none';render();return}const m=/([A-Za-z]*)$/.exec(ed.value),prefix=m?m[1].toUpperCase():'';const list=FUNCS.filter(f=>f.startsWith(prefix));if(list.length&&prefix){box.innerHTML=list.map(f=>`<div class="suggestion" data-f="${f}">${f}</div>`).join('');box.style.display='block';box.style.left=ed.style.left;box.style.top=`${parseFloat(ed.style.top)+28}px`}else box.style.display='none';render()}
function insertFormulaRef(reference){const ed=$('editor'),v=ed.value,pos=ed.selectionStart;const left=v.slice(0,pos),right=v.slice(ed.selectionEnd);const m=left.match(/[A-Z]+[1-9]\d*(?::[A-Z]+[1-9]\d*)?$/i);ed.value=(m?left.slice(0,-m[0].length):left)+reference+right;ed.focus();ed.selectionStart=ed.selectionEnd=(m?pos-m[0].length:pos)+reference.length;formulaAssist()}

function selectedChanges(valueFn){const b=bounds(),out=[];for(let r=b.r1;r<=b.r2;r++)for(let c=b.c1;c<=b.c2;c++)out.push({address:addr(r,c),value:valueFn(r,c)});return out}
async function copy(cut=false){const b=bounds(),rows=[];for(let r=b.r1;r<=b.r2;r++){const row=[];for(let c=b.c1;c<=b.c2;c++)row.push(raw(addr(r,c)));rows.push(row.join('\t'))}try{await navigator.clipboard.writeText(rows.join('\n'));if(cut)applyChanges(selectedChanges(()=>''),'Cut range');message(cut?'Range cut':'Range copied')}catch{message('Clipboard permission was denied',true)}}
function parseClipboard(text){const lines=text.replace(/\r/g,'').split('\n');if(lines.at(-1)==='')lines.pop();return lines.map(line=>line.includes('\t')?line.split('\t'):line.includes(',')?line.split(','):line.split(';'))}
async function paste(){try{pasteText(await navigator.clipboard.readText())}catch{message('Clipboard permission was denied',true)}}
function pasteText(text){const data=parseClipboard(text),start=parseAddr(addr(state.sel.r2,state.sel.c2)),out=[];data.forEach((row,ri)=>row.forEach((v,ci)=>{if(start.r+ri<=ROWS&&start.c+ci<=COLS)out.push({address:addr(start.r+ri,start.c+ci),value:v})}));applyChanges(out,'Paste range')}
function adjustFormula(v,dr,dc){return v.replace(/([A-Z]+)([1-9]\d*)/g,(_,co,ro)=>{const p=parseAddr(co+ro);return addr(Math.max(1,p.r+dr),Math.max(1,p.c+dc))})}
function fill(direction){const b=bounds(),vertical=direction==='down',out=[];const lanes=vertical?[...Array(b.c2-b.c1+1)].map((_,i)=>b.c1+i):[...Array(b.r2-b.r1+1)].map((_,i)=>b.r1+i);for(const lane of lanes){const len=vertical?b.r2-b.r1+1:b.c2-b.c1+1;if(len<2)continue;const at=i=>vertical?addr(b.r1+i,lane):addr(lane,b.c1+i),first=raw(at(0)),second=raw(at(1));const numeric=first!==''&&second!==''&&Number.isFinite(+first)&&Number.isFinite(+second),step=numeric?+second-+first:0;for(let i=1;i<len;i++){let v;if(numeric)v=String(+first+step*i);else{const source=at(0),sp=parseAddr(source),tp=parseAddr(at(i));v=first.startsWith('=')?adjustFormula(first,tp.r-sp.r,tp.c-sp.c):first}out.push({address:at(i),value:v})}}applyChanges(out,`Fill ${direction}`)}
function findMatches(){const q=$('find').value.toLowerCase();if(!q)return[];const out=[];for(let r=1;r<=ROWS;r++)for(let c=1;c<=COLS;c++)if(raw(addr(r,c)).toLowerCase().includes(q))out.push(addr(r,c));return out}
function findNext(){const m=findMatches();if(!m.length)return message('No matches',true);state.lastFind=(state.lastFind+1)%m.length;selectRange(m[state.lastFind]);message(`Match ${state.lastFind+1} of ${m.length}`)}
function replaceOne(){const a=addr(state.sel.r2,state.sel.c2),q=$('find').value;if(!q||!raw(a).toLowerCase().includes(q.toLowerCase()))return findNext();applyChanges([{address:a,value:raw(a).replace(new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i'),$('replace').value)}],`Replace in ${a}`);findNext()}
function replaceAll(){const q=$('find').value;if(!q)return message('Enter text to find',true);const re=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'),out=findMatches().map(a=>({address:a,value:raw(a).replace(re,$('replace').value)}));applyChanges(out,'Replace all');message(`Replaced ${out.length} cell(s)`)}

function scheduleSave(){clearTimeout(state.saveTimer);state.saveTimer=setTimeout(save,900)}
async function save(){if(state.saving||!state.dirty.size)return;if(state.conflicts.size)return message('Resolve the visible cell conflict before saving',true);state.saving=true;setSaveState('saving');try{const res=await fetch(`/api/workbooks/${encodeURIComponent(state.workbook.id)}/save`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({workbookId:state.workbook.id,baseRevision:state.revision,userId:$('user').value,sessionId:state.sessionId,workbook:state.workbook})});const data=await res.json();if(!res.ok){if(res.status===409&&data.conflicts){for(const c of data.conflicts)state.conflicts.add(c.address);showConflict(data.conflicts)}throw new Error(data.error)}state.workbook=data.workbook;state.sheet=state.workbook.sheets[0];state.revision=data.revision;state.revisions=data.revisions;state.dirty.clear();state.saving=false;setSaveState('saved');render();renderRevisions()}catch(e){state.saving=false;setSaveState('failed');message(e.message,true)}}
function showConflict(cs){$('conflict-text').textContent=cs.map(c=>`${c.address}: server “${c.serverValue}”, your draft “${c.localValue}”`).join('; ');$('conflict-banner').hidden=false;render()}
function connect(){const es=new EventSource(`/api/events?sessionId=${state.sessionId}`);es.addEventListener('presence',e=>{state.presence=JSON.parse(e.data);renderPresence()});es.addEventListener('revision',e=>remoteRevision(JSON.parse(e.data)));es.onopen=sendPresence}
function remoteRevision(e){if(e.workbookId!==state.workbook.id||e.revision<=state.revision)return;const clashes=[];for(const c of e.changes){if(c.sheetId!==state.sheet.id)continue;if(state.dirty.has(c.address)){clashes.push({address:c.address,serverValue:c.value,localValue:raw(c.address)});state.conflicts.add(c.address)}else put(c.address,c.value)}state.revision=e.revision;if(clashes.length)showConflict(clashes);else message(`Revision ${e.revision} received`);render();fetch('/api/bootstrap').then(r=>r.json()).then(x=>{state.revisions=x.revisions;renderRevisions()})}
async function sendPresence(){if(!state.workbook)return;const b=bounds();try{await fetch('/api/presence',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sessionId:state.sessionId,userId:$('user').value,selection:{start:addr(b.r1,b.c1),end:addr(b.r2,b.c2)}})})}catch{}}
function renderPresence(){if(!state.sheet)return;document.querySelectorAll('.cell.remote').forEach(e=>{e.classList.remove('remote','multi');e.style.removeProperty('--remote')});const remote=state.presence.filter(p=>p.sessionId!==state.sessionId),counts={};for(const p of state.presence)counts[p.userId]=(counts[p.userId]||0)+1;$('presence-count').textContent=Object.values(counts).reduce((a,b)=>a+b,0)+` view(s) open`;$('presence-legend').innerHTML=remote.map((p,i)=>{const color=colors[Math.abs(hash(p.sessionId))%colors.length];return `<span class="presence-chip"><i class="dot" style="background:${color}"></i>${escapeHtml(p.name)} · ${p.selection.start}${p.selection.end!==p.selection.start?':'+p.selection.end:''}</span>`}).join('');remote.forEach(p=>{const x=parseAddr(p.selection.start),y=parseAddr(p.selection.end),color=colors[Math.abs(hash(p.sessionId))%colors.length];if(!x||!y)return;for(let r=Math.min(x.r,y.r);r<=Math.max(x.r,y.r);r++)for(let c=Math.min(x.c,y.c);c<=Math.max(x.c,y.c);c++){const el=cellEl(r,c);if(el.classList.contains('remote'))el.classList.add('multi');el.classList.add('remote');el.style.setProperty('--remote',color)}})}
function hash(s){let h=0;for(const c of s)h=(h*31+c.charCodeAt(0))|0;return h}
function renderRevisions(){if(!state.revisions)return;$('revision-list').innerHTML=state.revisions.map(r=>`<div class="revision-item"><b>Revision ${r.revision}</b><br><small>${new Date(r.createdAt).toLocaleString()}</small><div class="revision-actions"><button data-preview="${r.revision}">Preview</button><button data-restore="${r.revision}">Restore as draft</button></div></div>`).join('')}
async function getRevision(n){const r=await fetch(`/api/workbooks/${state.workbook.id}/revisions/${n}`);if(!r.ok)throw new Error('Revision unavailable');return (await r.json()).content}
async function previewRevision(n){try{const w=await getRevision(n),before=state.workbook;state.workbook=w;state.sheet=w.sheets[0];render();message(`Previewing revision ${n}; select Restore to edit it`);setTimeout(()=>{state.workbook=before;state.sheet=before.sheets[0];render()},3500)}catch(e){message(e.message,true)}}
async function restoreRevision(n){try{const w=await getRevision(n),changes=[];const old=state.sheet.cells,neu=w.sheets[0].cells;for(const a of new Set([...Object.keys(old),...Object.keys(neu)]))if((old[a]||'')!==(neu[a]||''))changes.push({address:a,value:neu[a]||''});applyChanges(changes,`Restore revision ${n}`);message(`Revision ${n} loaded as an unsaved draft`)}catch(e){message(e.message,true)}}
