function bind(){const g=$('grid');g.onmousedown=e=>{const x=e.target.closest('.cell');if(!x)return;e.preventDefault();const r=+x.dataset.r,c=+x.dataset.c;if(S.editing&&$('editor').value.startsWith('=')){S.formulaPick=true;S.sel={r1:r,c1:c,r2:r,c2:c};insertRef(F.address(r,c));return}S.drag=true;select(r,c,e.shiftKey)};g.onmouseover=e=>{if(!S.drag&&!S.formulaPick)return;const x=e.target.closest('.cell');if(!x)return;S.sel.r2=+x.dataset.r;S.sel.c2=+x.dataset.c;if(S.formulaPick){const b=bounds();insertRef(b.r1===b.r2&&b.c1===b.c2?F.address(b.r1,b.c1):`${F.address(b.r1,b.c1)}:${F.address(b.r2,b.c2)}`)}else render()};document.onmouseup=()=>{if(S.drag){S.drag=false;sendPresence()}S.formulaPick=false};g.ondblclick=()=>edit();
 $('grid-wrap').onkeydown=e=>{const k=e.key,ctrl=e.ctrlKey||e.metaKey;if(ctrl&&k.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if(ctrl&&k.toLowerCase()==='y'){e.preventDefault();redo();return}if(ctrl&&k.toLowerCase()==='c'){e.preventDefault();copy();return}if(ctrl&&k.toLowerCase()==='x'){e.preventDefault();copy(true);return}if(ctrl&&k.toLowerCase()==='v'){e.preventDefault();paste();return}if(k==='Delete'||k==='Backspace'){e.preventDefault();change(selectionItems(()=>''),'Clear range');return}if(k==='F2'){e.preventDefault();edit();return}if(k.length===1&&!ctrl&&!e.altKey){e.preventDefault();edit(k);return}let dr=0,dc=0;if(k==='ArrowUp'||(k==='Enter'&&e.shiftKey))dr=-1;else if(k==='ArrowDown'||k==='Enter')dr=1;else if(k==='ArrowLeft'||(k==='Tab'&&e.shiftKey))dc=-1;else if(k==='ArrowRight'||k==='Tab')dc=1;else return;e.preventDefault();select(S.sel.r2+dr,S.sel.c2+dc,e.shiftKey&&k.startsWith('Arrow'))};
 $('editor').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();commit(e.shiftKey?-1:1)}else if(e.key==='Tab'){e.preventDefault();const p=F.parseAddr(e.target.dataset.address);commit();select(p.r,p.c+(e.shiftKey?-1:1))}else if(e.key==='Escape'){e.preventDefault();cancel()}};$('editor').oninput=assist;$('editor').onblur=()=>{if(S.editing&&!S.formulaPick)commit()};$('suggestions').onmousedown=e=>{e.preventDefault();if(e.target.dataset.f){const ed=$('editor'),n=ed.value.match(/[A-Za-z]*$/)?.[0].length||0;ed.setRangeText(`${e.target.dataset.f}(`,ed.selectionStart-n,ed.selectionEnd,'end');assist()}};
 $('formula-bar').onchange=e=>change([{address:F.address(S.sel.r2,S.sel.c2),value:e.target.value}],`Edit ${F.address(S.sel.r2,S.sel.c2)}`);$('formula-bar').onkeydown=e=>{if(e.key==='Enter')e.target.blur()};$('undo').onclick=undo;$('redo').onclick=redo;$('save').onclick=save;$('fill-down').onclick=()=>fill('down');$('fill-right').onclick=()=>fill('right');$('go').onclick=()=>selectRange($('name-box').value);$('name-box').onkeydown=e=>{if(e.key==='Enter')$('go').click()};$('find-next').onclick=findNext;$('replace-one').onclick=replaceOne;$('replace-all').onclick=replaceAll;$('history-toggle').onclick=()=>{$('side-panel').hidden=!$('side-panel').hidden;renderRevisions()};$('close-panel').onclick=()=>$('side-panel').hidden=true;$('cell-history').onclick=cellHistory;$('revision-list').onclick=e=>{if(e.target.dataset.preview)preview(+e.target.dataset.preview);if(e.target.dataset.restore)restore(+e.target.dataset.restore)};$('user').onchange=sendPresence;$('dismiss-conflict').onclick=()=>$('conflict-banner').hidden=true;document.addEventListener('paste',e=>{if(document.activeElement===$('grid-wrap')){e.preventDefault();pasteText(e.clipboardData.getData('text'))}})}
async function init(){build();bind();try{const r=await fetch('/api/bootstrap'),d=await r.json();if(!r.ok)throw Error(d.error);S.workbook=d.workbook;S.sheet=d.workbook.sheets[0];S.revision=d.revision;S.revisions=d.revisions;$('title').textContent=d.workbook.title;$('user').innerHTML=d.users.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');render();renderRevisions();connect();$('grid-wrap').focus()}catch(e){msg(e.message,true)}}init();
EOF


